#!/usr/bin/env bash
# QA suite #123: RES-04 configured attempt limits (1, 3, invalid 4) and RES-02 offline provider (connection refused, blackholed address). Injected provider (stub) except where labelled.
cd /home/stevdrey/Projects/Java/dokene-qa-run; . /home/stevdrey/qa123/s/base.sh; B1=$(cat /home/stevdrey/qa123/out/baseline.id); ST=/home/stevdrey/qa121/stub; OV=/home/stevdrey/qa123/ov2.yaml
. <(sed -n '/^rect()/,/^run()/p' /home/stevdrey/qa123/s/res0234.sh | head -n -1)
run() { : > $ST/fail; [ -n "$2" ] && echo "$2" > $ST/fail; local n0=$(wc -l < $ST/requests.log) a0=$(ai_rows); sleep 3.3; rect "$4"; local at=$(attempts $n0); echo "$1 -> http=$R_CODE status=$R_STATUS reason=$R_REASON retryable=$R_RETRY latency=${R_MS}ms | provider: $at | audit +$(( $(ai_rows) - a0 ))"; LAST=${at%% *}; : > $ST/fail; }
waitup() { for i in $(seq 1 60); do case "$(docker compose ps backend --format '{{.Status}}' 2>/dev/null)" in *healthy*) return 0;; esac; sleep 2; done; return 1; }
recreate() { printf 'services:\n  backend:\n    environment:\n      DOKENE_AI_PROVIDER: "openai"\n      DOKENE_AI_OPENAI_BASE_URL: "%s"\n%s\n' "$1" "$2" > $OV; COMPOSE_FILE=compose.yaml:$OV docker compose up -d --force-recreate --no-deps backend >/dev/null 2>&1; }
STUBURL=http://127.0.0.1:18080/v1
for n in 3 1; do echo "== max-attempts=$n, provider 503 always (injected)"; recreate $STUBURL "      DOKENE_AI_RETRY_MAX_ATTEMPTS: \"$n\""; waitup || echo "not healthy"; qa_login testoperator; TENANT=$A; run "503 always" "503:9" 0 ""; chk RES-04 "max-attempts=$n -> exactly $n provider attempt(s)" "$n" "$LAST"; run "429 Retry-After: 1 then success" "429:1:retry-after=1" 0 "" ; done
echo "== max-attempts=3 with the default 15 s deadline: 503 x2 then success"; recreate $STUBURL '      DOKENE_AI_RETRY_MAX_ATTEMPTS: "3"'; waitup; qa_login testoperator; TENANT=$A; run "503 twice then success" "503:2" 0 ""; chk RES-04 "503 twice then success with max-attempts=3: 3 attempts" 3 "$LAST"
echo "== max-attempts=4 (above the hard limit of 3) must fail fast"; recreate $STUBURL '      DOKENE_AI_RETRY_MAX_ATTEMPTS: "4"'; sleep 25; echo "  backend status: $(docker compose ps backend --format '{{.Status}}')"; docker compose logs --no-log-prefix backend 2>&1 | grep -E "max-attempts|IllegalArgument" | head -2 | cut -c1-240 | sed 's/^/  /'
echo "== RES-02 offline: connection refused (no listener) -- not a stub response, genuine network failure"; recreate "http://127.0.0.1:9/v1" ''; waitup; qa_login testoperator; TENANT=$A; a0=$(ai_rows); sleep 3.3; rect ""; echo "  http=$R_CODE status=$R_STATUS reason=$R_REASON retryable=$R_RETRY latency=${R_MS}ms audit +$(( $(ai_rows) - a0 )) ($(ai_last))"; chk RES-02 "refused connection: unavailable, retryable, bounded" "AI_UNAVAILABLE true yes" "$R_STATUS $R_RETRY $([ $R_MS -lt 15500 ] && echo yes || echo no)"
echo "== RES-02 offline: blackholed address (packets dropped; TCP connect never completes)"; recreate "http://10.255.255.1:81/v1" ''; waitup; qa_login testoperator; TENANT=$A; a0=$(ai_rows); sleep 3.3; rect ""; echo "  http=$R_CODE status=$R_STATUS reason=$R_REASON retryable=$R_RETRY latency=${R_MS}ms audit +$(( $(ai_rows) - a0 )) ($(ai_last))"; chk RES-02 "blackholed provider: unavailable/timeout, retryable, terminal latency bounded by the 15 s deadline" "AI_UNAVAILABLE true yes" "$R_STATUS $R_RETRY $([ $R_MS -lt 16500 ] && echo yes || echo no)"
echo "  deterministic work during the outage: queue $(getj testoperator '/api/follow-up-queue?limit=5' | jq '.items|length') items; manual follow-up on the baseline customer:"
api testoperator GET /api/customers/$B1/follow-up-policy ''; v=$(etag); api testoperator POST /api/customers/$B1/manual-follow-ups '{"notes":"RES-02 manual follow-up during the AI outage"}' -H "If-Match: \"$v\"" -H "Idempotency-Key: res02-$RUN"; echo "  manual follow-up http=$CODE"; chk RES-02 "manual follow-up works while the provider is unreachable" "201" "$CODE"
echo "== restore the stub configuration (max-attempts 2)"; recreate $STUBURL ''; waitup && echo "  backend healthy"
echo "PASS=$PASSN FAIL=$FAILN"
